def test_box_sizing_content_box_simple():
    config = Config()
    root = Node(config)
    root.position_type = PositionType.ABSOLUTE
    root.set_padding(Edge.LEFT, 5)
    root.set_padding(Edge.TOP, 5)
    root.set_padding(Edge.RIGHT, 5)
    root.set_padding(Edge.BOTTOM, 5)
    root.set_border(Edge.LEFT, 10)
    root.set_border(Edge.TOP, 10)
    root.set_border(Edge.RIGHT, 10)
    root.set_border(Edge.BOTTOM, 10)
    root.width = 100
    root.height = 100
    root.box_sizing = BoxSizing.CONTENT_BOX
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(130, abs=1e-4)
    assert root.layout.height == pytest.approx(130, abs=1e-4)
    root.calculate_layout(None, None, Direction.RTL)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(130, abs=1e-4)
    assert root.layout.height == pytest.approx(130, abs=1e-4)


